import sys
from collections import defaultdict

def main():
    N, X, D = map(int, sys.stdin.readline().split())
    if D == 0:
        if X == 0:
            print(1)
        else:
            print(N + 1)
        return
    ranges = defaultdict(list)
    d_abs = abs(D)
    for m in range(N + 1):
        min_sum = m * (m - 1) // 2
        max_sum = m * (2 * N - m - 1) // 2
        S_min = m * X + D * min_sum
        S_max = m * X + D * max_sum
        start = min(S_min, S_max)
        end = max(S_min, S_max)
        c = (m * X) % D
        ranges[c].append((start, end))
    total = 0
    for c in ranges:
        ranges_list = sorted(ranges[c], key=lambda x: x[0])
        merged = []
        for s, e in ranges_list:
            if not merged:
                merged.append([s, e])
            else:
                last_s, last_e = merged[-1]
                if s <= last_e:
                    new_s = last_s
                    new_e = max(last_e, e)
                    merged[-1] = [new_s, new_e]
                else:
                    merged.append([s, e])
        for s, e in merged:
            count = ((e - s) // d_abs) + 1
            total += count
    print(total)

if __name__ == "__main__":
