import sys

def sum_geo_helper(k, x, M):
    if k == 0:
        return 0
    if x == 1:
        return k % M
    def helper(k):
        if k == 0:
            return 0
        if k == 1:
            return 1 % M
        if k % 2 == 0:
            half = helper(k // 2)
            pow_x_half = pow(x, k//2, M)
            return (half * (1 + pow_x_half)) % M
        else:
            return (helper(k-1) + pow(x, k-1, M)) % M
    return helper(k)

def sum_m_xm_helper(k, x, M):
    if k == 0:
        return 0
    if x == 1:
        return (k * (k - 1) // 2) % M
    def helper(k):
        if k == 0:
            return 0
        if k == 1:
            return 0 % M
        if k % 2 == 0:
            t = k // 2
            part1 = helper(t)
            pow_x_t = pow(x, t, M)
            sum_geo_t = sum_geo_helper(t, x, M)
            term1 = (part1 * (1 + pow_x_t)) % M
            term2 = (t * pow_x_t % M) * sum_geo_t % M
            return (term1 + term2) % M
        else:
            t = k // 2
            part = helper(2*t)
            pow_x_2t = pow(x, 2*t, M)
            return (part + (2*t) * pow_x_2t) % M
    return helper(k)

def main():
    input = sys.stdin.read().split()
    L = int(input[0])
    A = int(input[1])
    B = int(input[2])
    M = int(input[3])
    res = 0
    for l in range(1, 19):
        low = 10 ** (l-1)
        up = 10 ** l - 1
        numerator_i_min = low - A
        if numerator_i_min <= 0:
            i_min = 0
        else:
            i_min = (numerator_i_min + B - 1) // B
        numerator_i_max = up - A
        if numerator_i_max < 0:
            i_max = -1
        else:
            i_max = numerator_i_max // B
        i_max = min(i_max, L-1)
        if i_min > i_max:
            continue
        k = i_max - i_min + 1
        t0 = A + B * i_min
        x = pow(10, l, M)
        sum_geo = sum_geo_helper(k, x, M)
        sum_m_xm = sum_m_xm_helper(k, x, M)
        term1 = (t0 * sum_geo) % M
        term2 = (B * (( (k-1) * sum_geo - sum_m_xm ) % M )) % M
        S = (term1 + term2) % M
        pow_x_k = pow(x, k, M)
        res = (res * pow_x_k + S) % M
    print(res)

if __name__ == "__main__":
