import sys

def factorize(n):
    factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

def generate_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        temp = []
        for d in divisors:
            current = d
            for e in range(1, exp + 1):
                current *= p
                temp.append(current)
        divisors += temp
    return divisors

def main():
    N = int(sys.stdin.readline())
    if N == 1:
        print(0)
        return

    N_minus_1 = N - 1
    factors_N = factorize(N)
    factors_N_minus_1 = factorize(N_minus_1)

    divisors_N = generate_divisors(factors_N)
    divisors_N_minus_1 = generate_divisors(factors_N_minus_1)

    count1 = 0
    for d in divisors_N_minus_1:
        if d >= 2:
            count1 += 1

    count2 = 0
    for K in divisors_N:
        if K == 1:
            continue
        exponents_in_K = {}
        for p in factors_N:
            cnt = 0
            temp = K
            while temp % p == 0:
                cnt += 1
                temp = temp // p
            exponents_in_K[p] = cnt
        relevant_primes = [p for p in factors_N if exponents_in_K[p] > 0]
        if not relevant_primes:
            continue
        a_list = []
        for p in relevant_primes:
            e_p = factors_N[p]
            f_p = exponents_in_K[p]
            a_p = e_p // f_p
            a_list.append(a_p)
        a = min(a_list)
        K_power_a = pow(K, a)
        M = N // K_power_a
        if M % K == 1:
            count2 += 1

    print(count1 + count2)

