def generate_divisors(factors):
    divisors = [1]
    for prime, exp in factors.items():
        current_length = len(divisors)
        prime_powers = [prime**e for e in range(1, exp+1)]
        for d in divisors[:current_length]:
            for power in prime_powers:
                divisors.append(d * power)
    return divisors

def main():
