import math

def get_divisors(x):
    divisors = set()
    for i in range(1, int(math.isqrt(x)) + 1):
        if x % i == 0:
            divisors.add(i)
            divisors.add(x // i)
    return divisors

def is_valid(m, k):
    while m >= k:
        if m % k == 0:
            m = m // k
        else:
            m = m % k
    return m == 1

def main():
    import sys
    input = sys.stdin.read
    N = int(input())

    if N == 1:
        print(0)
        return

    # Compute A: number of divisors of N-1 >=2
    x = N - 1
    divisors_n_minus_1 = get_divisors(x)
    A = 0
    for d in divisors_n_minus_1:
        if d >= 2:
            A += 1

    # Compute B: for each divisor of N >=2, check is_valid(N//k, k)
    divisors_n = get_divisors(N)
    B = 0
    for k in divisors_n:
        if k >= 2:
            m = N // k
            if is_valid(m, k):
                B += 1

    print(A + B)

if __name__ == "__main__":
    main()
