        for k in range(K+1):
            # Iterate through all possible previous values in dp[i-1][k]
            for v_prev, sum_prev in dp[i-1][k].items():
                # Option 1: do not change column i
                new_value = H[i-1]
                contribution = max(0, new_value - v_prev)
                new_sum = sum_prev + contribution
                if new_value in dp[i][k]:
                    if new_sum < dp[i][k][new_value]:
                        dp[i][k][new_value] = new_sum
                else:
                    dp[i][k][new_value] = new_sum
                # Option 2: change column i
                if k < K:
                    new_value_change = v_prev
                    contribution_change = 0
                    new_sum_change = sum_prev + contribution_change
                    if new_value_change in dp[i][k+1]:
                        if new_sum_change < dp[i][k+1][new_value_change]:
                            dp[i][k+1][new_value_change] = new_sum_change
                    else:
                        dp[i][k+1][new_value_change] = new_sum_change

    # Find the minimum sum in dp[N][k] for k in 0..K
    min_sum = float('inf')
    for k in range(K+1):
        if dp[N][k]:
            min_sum = min(min_sum, min(dp[N][k].values()))
