                    if new_a <= max_sum and new_b <= max_sum:
                        if dp[new_a][new_b] > dp[a][b] + c_i:
                            dp[new_a][new_b] = dp[a][b] + c_i

    min_cost = INF
    for a in range(1, max_sum + 1):
        for b in range(1, max_sum + 1):
            if a * M_b == b * M_a:
                if dp[a][b] < min_cost:
                    min_cost = dp[a][b]

    print(-1 if min_cost == INF else min_cost)

if __name__ == "__main__":
    main()
