import sys

def sieve(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    primes = [i for i, val in enumerate(is_prime) if val]
    return primes

def count_exponent(n, p):
    count = 0
    while n > 0:
        n = n // p
        count += n
    return count

def main():
    N = int(sys.stdin.readline())
    primes = sieve(N)
    if not primes:
        print(0)
        return
    exponents = [count_exponent(N, p) for p in primes]
    factorizations = [
        [75],
        [3, 25], [25, 3],
        [5, 15], [15, 5],
        [3, 5, 5], [5, 3, 5], [5, 5, 3]
    ]
    count = 0
    for fact in factorizations:
        k = len(fact)
        if len(primes) < k:
            continue
        valid = True
        for i in range(k):
            if exponents[i] < (fact[i] - 1):
                valid = False
                break
        if valid:
            count += 1
    print(count)

if __name__ == "__main__":
    main()
