import sys
from itertools import combinations

def get_primes(n):
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    primes = [i for i, is_prime in enumerate(sieve) if is_prime]
    return primes

def legendre(n, p):
    count = 0
    power = p
    while power <= n:
        count += n // power
        power *= p
    return count

def generate_factor_lists():
    factors_of_75 = [1, 3, 5, 15, 25, 75]
    result = []
    def dfs(current_product, path):
        if current_product == 75:
            result.append(path.copy())
            return
        for factor in factors_of_75:
            if current_product * factor > 75:
                continue
            path.append(factor)
            dfs(current_product * factor, path)
            path.pop()
    dfs(1, [])
    return result

def main():
    N = int(sys.stdin.readline())
    primes = get_primes(N)
    if not primes:
        print(0)
        return
    prime_to_exponent = {p: legendre(N, p) for p in primes}
    factor_lists = generate_factor_lists()
    total = 0
    for factor_list in factor_lists:
        required_exponents = [f - 1 for f in factor_list]
        m = len(required_exponents)
        if m > len(primes):
            continue
        count = 0
        for combo in combinations(primes, m):
            valid = True
            for i in range(m):
                p = combo[i]
                if prime_to_exponent[p] < required_exponents[i]:
                    valid = False
                    break
            if valid:
                count += 1
        total += count
    print(total)

if __name__ == "__main__":
    main()
